{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "type": [
        "string",
        "null"
      ]
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "type": [
        "string",
        "null"
      ]
    },
    "filename": {
      "description": "The filename for display purposes.",
      "type": [
        "string",
        "null"
      ]
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the array.",
      "type": [
        "string",
        "null"
      ]
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    }
  },
  "required": [
    "items"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.BooleanInputSchema",
  "description": "Schema for a boolean input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the boolean.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.IntegerInputSchema",
  "description": "Schema for an integer input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the integer.",
      "type": [
        "string",
        "null"
      ]
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "type": [
        "integer",
        "null"
      ],
      "format": "int64"
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "type": [
        "integer",
        "null"
      ],
      "format": "int64"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.InputSchema",
  "description": "Schema for validating Function input.\n\nDefines the expected structure and constraints for input data.\nUsed by remote Functions to document and validate their inputs.",
  "oneOf": [
    {
      "description": "An object with named properties.",
      "type": "object",
      "properties": {
        "Object": {
          "$ref": "functions.expression.ObjectInputSchema"
        }
      },
      "required": [
        "Object"
      ],
      "additionalProperties": false
    },
    {
      "description": "An array of items.",
      "type": "object",
      "properties": {
        "Array": {
          "$ref": "functions.expression.ArrayInputSchema"
        }
      },
      "required": [
        "Array"
      ],
      "additionalProperties": false
    },
    {
      "description": "A string value.",
      "type": "object",
      "properties": {
        "String": {
          "$ref": "functions.expression.StringInputSchema"
        }
      },
      "required": [
        "String"
      ],
      "additionalProperties": false
    },
    {
      "description": "An integer value.",
      "type": "object",
      "properties": {
        "Integer": {
          "$ref": "functions.expression.IntegerInputSchema"
        }
      },
      "required": [
        "Integer"
      ],
      "additionalProperties": false
    },
    {
      "description": "A floating-point number.",
      "type": "object",
      "properties": {
        "Number": {
          "$ref": "functions.expression.NumberInputSchema"
        }
      },
      "required": [
        "Number"
      ],
      "additionalProperties": false
    },
    {
      "description": "A boolean value.",
      "type": "object",
      "properties": {
        "Boolean": {
          "$ref": "functions.expression.BooleanInputSchema"
        }
      },
      "required": [
        "Boolean"
      ],
      "additionalProperties": false
    },
    {
      "description": "An image (URL or base64).",
      "type": "object",
      "properties": {
        "Image": {
          "$ref": "functions.expression.ImageInputSchema"
        }
      },
      "required": [
        "Image"
      ],
      "additionalProperties": false
    },
    {
      "description": "Audio content.",
      "type": "object",
      "properties": {
        "Audio": {
          "$ref": "functions.expression.AudioInputSchema"
        }
      },
      "required": [
        "Audio"
      ],
      "additionalProperties": false
    },
    {
      "description": "Video content.",
      "type": "object",
      "properties": {
        "Video": {
          "$ref": "functions.expression.VideoInputSchema"
        }
      },
      "required": [
        "Video"
      ],
      "additionalProperties": false
    },
    {
      "description": "A file.",
      "type": "object",
      "properties": {
        "File": {
          "$ref": "functions.expression.FileInputSchema"
        }
      },
      "required": [
        "File"
      ],
      "additionalProperties": false
    },
    {
      "description": "A union of schemas - input must match at least one.",
      "type": "object",
      "properties": {
        "AnyOf": {
          "$ref": "functions.expression.AnyOfInputSchema"
        }
      },
      "required": [
        "AnyOf"
      ],
      "additionalProperties": false
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.FileInputSchema",
  "description": "Schema for a file input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected file.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.NumberInputSchema",
  "description": "Schema for a floating-point number input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the number.",
      "type": [
        "string",
        "null"
      ]
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "type": [
        "number",
        "null"
      ],
      "format": "double"
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "type": [
        "number",
        "null"
      ],
      "format": "double"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.Expression",
  "description": "An expression that can be either JMESPath or Starlark.\n\nSerializes as `{\"$jmespath\": \"...\"}` or `{\"$starlark\": \"...\"}` in JSON.\n\n# Examples\n\nJMESPath:\n```json\n{\"$jmespath\": \"input.items[0].name\"}\n```\n\nStarlark:\n```json\n{\"$starlark\": \"input['items'][0]['name']\"}\n```",
  "oneOf": [
    {
      "description": "A JMESPath expression.",
      "type": "object",
      "properties": {
        "JMESPath": {
          "type": "string"
        }
      },
      "required": [
        "JMESPath"
      ],
      "additionalProperties": false
    },
    {
      "description": "A Starlark expression.",
      "type": "object",
      "properties": {
        "Starlark": {
          "type": "string"
        }
      },
      "required": [
        "Starlark"
      ],
      "additionalProperties": false
    },
    {
      "description": "A predefined special expression variant.",
      "type": "object",
      "properties": {
        "Special": {
          "$ref": "functions.expression.Special"
        }
      },
      "required": [
        "Special"
      ],
      "additionalProperties": false
    }
  ]
}
